Custom.Code:
try {
  int count = 0;
  Func<Styx.SkillLine, bool> has = delegate(Styx.SkillLine line) {
    try { return Me.GetSkill(line).MaxValue > 0; } catch { return false; }
  };
  if (has(Styx.SkillLine.Alchemy)) count++;
  if (has(Styx.SkillLine.Blacksmithing)) count++;
  if (has(Styx.SkillLine.Enchanting)) count++;
  if (has(Styx.SkillLine.Engineering)) count++;
  if (has(Styx.SkillLine.Herbalism)) count++;
  if (has(Styx.SkillLine.Inscription)) count++;
  if (has(Styx.SkillLine.Jewelcrafting)) count++;
  if (has(Styx.SkillLine.Leatherworking)) count++;
  if (has(Styx.SkillLine.Mining)) count++;
  if (has(Styx.SkillLine.Skinning)) count++;
  if (has(Styx.SkillLine.Tailoring)) count++;
  AppDomain.CurrentDomain.SetData("ULT_PRIMARIES", count);
  Log(Colors.DeepSkyBlue,"Ultimate 1-90:", Colors.White, "Primary professions known: {0}/2; configured: {1}, {2}", count, AppDomain.CurrentDomain.GetData("ULT_P1"), AppDomain.CurrentDomain.GetData("ULT_P2"));
} catch (Exception ex) {
  AppDomain.CurrentDomain.SetData("ULT_PRIMARIES", -1);
  Log(Colors.Orange,"Ultimate 1-90:", Colors.Yellow, "Skill scan failed: {0}", ex.Message);
}

AppDomain.CurrentDomain.SetData("ULT_PROMPTED", true);
try {
  string[] options = new string[] { "None", "Alchemy", "Blacksmithing", "Enchanting", "Engineering", "Herbalism", "Inscription", "Jewelcrafting", "Leatherworking", "Mining", "Skinning", "Tailoring" };
  using (var form = new System.Windows.Forms.Form()) {
    form.Text = "Ultimate 1-90 - Choose 2 Primary Professions";
    form.StartPosition = System.Windows.Forms.FormStartPosition.CenterScreen;
    form.FormBorderStyle = System.Windows.Forms.FormBorderStyle.FixedDialog;
    form.MaximizeBox = false;
    form.MinimizeBox = false;
    form.ClientSize = new System.Drawing.Size(560, 255);
    form.TopMost = true;

    var label = new System.Windows.Forms.Label();
    label.SetBounds(12, 12, 536, 78);
    label.Text = string.Format("{0} (level {1} {2} {3})\r\nChoose up to two primary professions.\r\nThe controller saves your choices in PB Settings and maps them to available profiles in PrimaryProfessions mode.\r\nCooking, Fishing and Archaeology are secondary and do not use these two slots.", Me.Name, Me.Level, Me.Race, Me.Class);
    form.Controls.Add(label);

    var firstLabel = new System.Windows.Forms.Label(); firstLabel.Text = "Profession 1:"; firstLabel.SetBounds(12, 100, 90, 23); form.Controls.Add(firstLabel);
    var secondLabel = new System.Windows.Forms.Label(); secondLabel.Text = "Profession 2:"; secondLabel.SetBounds(12, 138, 90, 23); form.Controls.Add(secondLabel);

    var first = new System.Windows.Forms.ComboBox(); first.SetBounds(112, 96, 420, 23); first.DropDownStyle = System.Windows.Forms.ComboBoxStyle.DropDownList; first.Items.AddRange(options);
    var second = new System.Windows.Forms.ComboBox(); second.SetBounds(112, 134, 420, 23); second.DropDownStyle = System.Windows.Forms.ComboBoxStyle.DropDownList; second.Items.AddRange(options);
    string configured1 = (string)AppDomain.CurrentDomain.GetData("ULT_P1");
    string configured2 = (string)AppDomain.CurrentDomain.GetData("ULT_P2");
    first.SelectedItem = options.FirstOrDefault(o => o.Equals(configured1, StringComparison.OrdinalIgnoreCase)) ?? "Mining";
    second.SelectedItem = options.FirstOrDefault(o => o.Equals(configured2, StringComparison.OrdinalIgnoreCase)) ?? "Herbalism";
    form.Controls.Add(first); form.Controls.Add(second);

    var ok = new System.Windows.Forms.Button(); ok.Text = "Save Choices"; ok.SetBounds(316, 190, 105, 32);
    var cancel = new System.Windows.Forms.Button(); cancel.Text = "Cancel"; cancel.SetBounds(427, 190, 105, 32); cancel.DialogResult = System.Windows.Forms.DialogResult.Cancel;
    ok.Click += delegate {
      if ((string)first.SelectedItem == (string)second.SelectedItem && (string)first.SelectedItem != "None") {
        System.Windows.Forms.MessageBox.Show("Choose two different professions, or set Profession 2 to None.", "Ultimate 1-90");
        return;
      }
      form.DialogResult = System.Windows.Forms.DialogResult.OK;
      form.Close();
    };
    form.Controls.Add(ok); form.Controls.Add(cancel); form.AcceptButton = ok; form.CancelButton = cancel;

    if (form.ShowDialog() == System.Windows.Forms.DialogResult.OK) {
      string p1 = ((string)first.SelectedItem ?? "None").Trim().ToLowerInvariant();
      string p2 = ((string)second.SelectedItem ?? "None").Trim().ToLowerInvariant();
      AppDomain.CurrentDomain.SetData("ULT_P1", p1); AppDomain.CurrentDomain.SetData("ULT_P2", p2);
      try { Settings["Primary Profession 1"] = p1; Settings["Primary Profession 2"] = p2; } catch (Exception saveEx) { Log(Colors.Orange,"Ultimate 1-90:", Colors.Yellow, "Settings save warning: {0}", saveEx.Message); }
      Log(Colors.DeepSkyBlue,"Ultimate 1-90:", Colors.LightGreen, "Saved profession choices: {0}, {1}", p1, p2);
    } else {
      Log(Colors.Orange,"Ultimate 1-90:", Colors.Yellow, "Profession chooser cancelled; no changes made.");
    }
  }
} catch (Exception ex) {
  Log(Colors.Red,"Ultimate 1-90:", Colors.White, "Profession chooser failed: {0}. Set Primary Profession 1/2 manually in PB Settings.", ex.Message);
}

try {
  string path = ((string)Settings["Questing Profile Override"]).Trim();
  if (!System.IO.Path.IsPathRooted(path)) path = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(ProfessionbuddyBot.Instance.CurrentProfile.XmlPath), path);
  ProfileManager.LoadNew(path, false);
  Log(Colors.DeepSkyBlue,"Ultimate 1-90:", Colors.LightGreen, "Loaded questing override: {0}", path);
} catch (Exception ex) { Log(Colors.Red,"Ultimate 1-90:", Colors.White, "Questing override failed: {0}", ex.Message); }

try {
  string rel = null;
  if (Me.Level <= 12) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\Classic\[A - Quest] 1-58 [Kick]\[A - Quest] 1-12 Auto-Loader [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\Classic\[H - Quest] 1-58 [Kick]\[H - Quest] 1-12 Auto-Loader [Kick].xml";
  } else if (Me.Level <= 57) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\Classic\[A - Quest] 1-58 [Kick]\[A - Quest] EK 12-58 [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\Classic\[H - Quest] 1-58 [Kick]\[H - Quest] 12-58 K-EK [Kick].xml";
  } else if (Me.Level <= 67) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\BC\[Fly][A - Quest] BC 58-70 [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\BC\[Fly][H - Quest] BC 58-70 [Kick].xml";
  } else if (Me.Level <= 79) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\LK\[Fly][A - Quest] LK 68-80 [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\LK\[Fly][H - Quest] LK 68-80 [Kick].xml";
  } else if (Me.Level <= 81) rel = @"..\..\1-90 Questing Profile Pack\Cata\[Fly][N - Quest] Hyjal 80-82 [Kick].xml";
  else if (Me.Level == 82) rel = @"..\..\1-90 Questing Profile Pack\Cata\[Fly][N - Quest] Deepholm 82-84 [Kick].xml";
  else if (Me.Level == 83) rel = @"..\..\1-90 Questing Profile Pack\Cata\[Fly][N - Quest] Uldum 83-85 [Kick].xml";
  else if (Me.Level == 84) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\Cata\[Fly][A - Quest] Twilight Highlands 84-85 [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\Cata\[Fly][H - Quest] Twilight Highlands 84-85 [Kick].xml";
  } else if (Me.Level == 85) {
    if (Me.IsAlliance) rel = @"..\..\1-90 Questing Profile Pack\MoP\[A - Quest] 85-86 The Jade Forest [Kick].xml";
    else if (Me.IsHorde) rel = @"..\..\1-90 Questing Profile Pack\MoP\[H - Quest] 85-86 The Jade Forest [Kick].xml";
  } else if (Me.Level == 86) rel = @"..\..\1-90 Questing Profile Pack\MoP\[N - Quest] 86-87 Valley of the Four Winds [Kick].xml";
  else if (Me.Level == 87) rel = @"..\..\1-90 Questing Profile Pack\MoP\[N - Quest] 87-88 Krasarang Wilds [Kick].xml";
  else if (Me.Level == 88) rel = @"..\..\1-90 Questing Profile Pack\MoP\[N - Quest] 88-89 Kun-Lai Summit [Kick].xml";
  else if (Me.Level == 89) rel = @"..\..\1-90 Questing Profile Pack\MoP\[N - Quest] 89-90 Townlong Steppes [Kick].xml";

  if (rel == null) {
    Log(Colors.Orange,"Ultimate 1-90:", Colors.Yellow, "No faction/level questing mapping for this toon. Choose a faction or set Questing Profile Override.");
  } else {
    string full = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(ProfessionbuddyBot.Instance.CurrentProfile.XmlPath), rel);
    if (!System.IO.File.Exists(full)) {
      Log(Colors.Red,"Ultimate 1-90:", Colors.White, "Questing profile not found: {0}", full);
    } else {
      Log(Colors.DeepSkyBlue,"Ultimate 1-90:", Colors.LightGreen, "Questing handoff (Lv{0}, {1}): {2}", Me.Level, Me.Race, rel);
      ProfileManager.LoadNew(full, false);
    }
  }
} catch (Exception ex) { Log(Colors.Red,"Ultimate 1-90:", Colors.White, "Questing auto-selection failed: {0}", ex.Message); }
